+
+  test('re-running with the same args is a no-op (skipped)', () => {
+    const first = run(['Foo', '--parent', 'app/components'], {cwd: sandbox.root});
+    expect(first).toBe(0);
+
+    const second = run(['Foo', '--parent', 'app/components', '--json'], {
+      cwd: sandbox.root,
+    });
+    expect(second).toBe(0);
