+  (globalThis as {__gaiaRouteRoot?: string}).__gaiaRouteRoot = fakeRoot;
+
+  return {
+    cleanup: () => {
+      delete (globalThis as {__gaiaRouteRoot?: string}).__gaiaRouteRoot;
+      rmSync(fakeRoot, {force: true, recursive: true});
+    },
+    fakeRoot,
+  };
+};
