+  return {
+    NAME_UPPER: toUpperConst(name),
+    Plural: toPascal(name),
+    Singular: toPascal(singularKebab),
+    name,
+    plural: toCamel(name),
+    singular: toCamel(singularKebab),
+  };
+};
