+const MOCK_IMPORT_LINES: Record<Endpoint, string> = {
+  delete: "import del from './delete';",
+  get: "import get from './get';",
+  post: "import post from './post';",
+  put: "import put from './put';",
+};
+
+const MOCK_ARRAY_TOKENS: Record<Endpoint, string> = {
+  delete: 'del',
+  get: '...get',
+  post: 'post',
+  put: 'put',
+};
