+    .map((endpoint) => MOCK_IMPORT_LINES[endpoint])
+    .join('\n');
+  const handlersArray = ALL_ENDPOINTS.filter((endpoint) => endpoints.has(endpoint))
+    .map((endpoint) => MOCK_ARRAY_TOKENS[endpoint])
