+type Sandbox = {
+  cleanup: () => void;
+  root: string;
+  statePath: string;
+};
+
+const setupSandbox = (): Sandbox => {
+  const root = mkdtempSync(path.join(tmpdir(), 'gaia-setup-'));
+  execFileSync('git', ['init', '-q'], {cwd: root});
+
+  return {
+    cleanup: () => {
+      rmSync(root, {force: true, recursive: true});
+    },
+    root,
+    statePath: path.join(root, '.gaia', 'local', 'setup-state.json'),
+  };
