+    sandbox.writeTree('baseline', 'app/foo.ts', 'export const X = 1;\n');
+    sandbox.writeTree('latest', 'app/foo.ts', 'export const X = 2;\n');
+    sandbox.writeManifest({'app/foo.ts': 'owned'});
+
+    const exit = run(baseArgv(sandbox), {cwd: sandbox.cwd});
