+import {structuredError} from '../stderr.js';
+import {
+  loadManifest,
+  type Manifest,
+  type NormalizedClass,
+} from './util/manifest.js';
+import {
+  bytesEqual,
+  cleanMerge,
+  snapshot,
+  unifiedDiff,
+} from './util/three-way.js';
