+export type ConflictReport = {
+  class: ConflictClass;
+  path: string;
+  patch_path: string;
+};
+
+export type UpdateMergeReport = {
+  overwrite: string[];
+  skip: string[];
+  merge: string[];
+  add: string[];
+  delete: string[];
+  conflicts: ConflictReport[];
+};
+
+type Flags = {
+  baseline: string;
+  latest: string;
+  manifest: string;
+  json: boolean;
+};
+
+type ParsedFlagsSuccess = {
+  flags: Flags;
+  ok: true;
+};
+
+type ParsedFlagsFailure = {
+  message: string;
+  ok: false;
+};
+
+type ParsedFlagsResult = ParsedFlagsFailure | ParsedFlagsSuccess;
+
+const takeValue = (
+  argv: readonly string[],
+  index: number,
+  flag: string
+): {message: string; ok: false} | {ok: true; value: string} => {
+  const value = argv[index];
+
+  if (value === undefined) return {message: `${flag} requires a value`, ok: false};
+
+  return {ok: true, value};
+};
+
+const parseFlags = (argv: readonly string[]): ParsedFlagsResult => {
+  let baseline: string | undefined;
+  let latest: string | undefined;
+  let manifest: string | undefined;
