+      if (!taken.ok) return taken;
+      latest = taken.value;
+      index += 1;
+      continue;
+    }
+
+    if (token === '--manifest') {
+      const taken = takeValue(argv, index + 1, '--manifest');
+
+      if (!taken.ok) return taken;
+      manifest = taken.value;
+      index += 1;
