+  if (!existsSync(baselineDir) || !statSync(baselineDir).isDirectory()) {
+    structuredError({
+      code: 'baseline_missing',
+      message: `--baseline directory not found: ${baselineDir}`,
+      subcommand: 'update merge',
+    });
