+    return EXIT_CODES.UNKNOWN_SUBCOMMAND;
+  }
+
+  if (!existsSync(latestDir) || !statSync(latestDir).isDirectory()) {
+    structuredError({
+      code: 'latest_missing',
+      message: `--latest directory not found: ${latestDir}`,
+      subcommand: 'update merge',
+    });
