+  if (result === null) return [];
+
+  return result
+    .split('\n')
+    .map((line) => line.trim())
+    .filter((line) => line.length > 0);
+};
+
+type RawRecord = {
+  body: string;
+  sha: string;
+  subject: string;
+};
+
+type ChunkParse = {
+  precedingStat: string;
+  record: RawRecord | null;
+};
