+  while (bodyLines.length > 0 && (bodyLines.at(-1) ?? '').trim() === '') {
+    bodyLines.pop();
+  }
+
+  return {
+    precedingStat,
+    record: {body: bodyLines.join('\n'), sha, subject},
+  };
