+  sinceSha: string,
+  cwd: string
+): CommitDetail[] => {
+  const recordSeparator = '---END-COMMIT---';
+  const raw = tryRunGit(
+    [
+      'log',
+      '--no-merges',
+      '--reverse',
+      '--shortstat',
+      `--format=COMMIT %H%n%s%n%b%n${recordSeparator}`,
+      `${sinceSha}..HEAD`,
+    ],
+    {cwd}
+  );
