+  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
+    const inner = trimmed.slice(1, -1).trim();
+
+    if (inner === '') return [];
+
+    return inner
+      .split(',')
+      .map((entry) => stripQuotes(entry.trim()))
+      .filter((entry) => entry.length > 0);
+  }
