+
+    const exit = run([], {cwd: sandbox.root, runner});
+    expect(exit).toBe(0);
+    expect(stdio.outputs.join('').trim()).toBe('v1.2.3 -> v1.3.0 (minor)');
+
+    // Did NOT write
